  q(EKG,'How long is a normal PR interval?','0.12 to 0.20 seconds',['0.40 to 0.60 seconds','0.02 to 0.04 seconds','1.0 to 2.0 seconds'],'D','A PR interval longer than 0.20 seconds suggests a first-degree heart block.',NHA),
  q(EKG,'Which patient position is used for a routine 12-lead EKG?','Supine, arms at the sides',['Standing with arms raised','Prone on the stomach','Sitting with legs crossed'],'A','Lying supine, relaxed and still helps prevent muscle tremor artifact on the tracing.',NHA),
  q(EKG,'Using the 1500 method, what is the heart rate if there are 15 small boxes between R waves?','100 bpm',['60 bpm','75 bpm','150 bpm'],'B','Divide 1,500 by the number of small boxes between R waves: 1,500 ÷ 15 = 100 bpm.',NHA)
